import java.nio.charset.StandardCharsets;

/** Encode browser-permitted query characters before Java HTTP URI parsing. */
final class LocalUrlSafety {
 private LocalUrlSafety() {}
 static byte[] script(){return "/* NOON_LOCAL_URL_SAFETY: Java URI rejects characters Chromium permits in queries. */\n(function(w,d){\n 'use strict';\n if(w.__noonLocalUrlSafety)return;\n w.__noonLocalUrlSafety=true;\n function escapeUnsafe(value){\n  return String(value).replace(/%(?![0-9a-f]{2})|[\\u0000-\\u0020\\u007f<>\"{}|\\\\^`]/gi,function(ch){\n   return ch==='%'?'%25':encodeURIComponent(ch);\n  });\n }\n function localUrl(value){\n  if(value==null)return value;\n  var text=String(value),link=d.createElement('a');\n  // Preserve other protocols and external destinations exactly as supplied.\n  if(/^\\s*(?:javascript|data|mailto|tel|about|blob):/i.test(text))return value;\n  link.href=text;\n  if(link.protocol!==w.location.protocol||link.host!==w.location.host)return value;\n  // Fragments are browser-only and must keep their existing hit/scroll semantics.\n  var hash=text.indexOf('#');\n  return hash<0?escapeUnsafe(text):escapeUnsafe(text.slice(0,hash))+text.slice(hash);\n }\n w.noonSafeLocalUrl=localUrl;\n var open=w.open;\n w.open=function(url){var args=Array.prototype.slice.call(arguments);if(args.length)args[0]=localUrl(url);return open.apply(this,args);};\n function fixLink(event){\n  var node=event.target;\n  while(node&&node.nodeType!==1)node=node.parentNode;\n  while(node){\n   if(/^(a|area)$/i.test(node.tagName||'')){\n    var raw=node.getAttribute('href');if(raw!=null){var safe=localUrl(raw);if(safe!==raw)node.setAttribute('href',safe);}return;\n   }\n   node=node.parentNode;\n  }\n }\n d.addEventListener('click',fixLink,true);\n d.addEventListener('auxclick',fixLink,true);\n d.addEventListener('contextmenu',fixLink,true);\n // Search previews can navigate an iframe without a click on its destination.\n function protectFrame(type){\n  if(!type)return;\n  var proto=type.prototype,descriptor=Object.getOwnPropertyDescriptor(proto,'src');\n  if(!descriptor||!descriptor.configurable||!descriptor.set||!descriptor.get)return;\n  try{Object.defineProperty(proto,'src',{configurable:true,enumerable:descriptor.enumerable,get:descriptor.get,set:function(value){descriptor.set.call(this,localUrl(value));}});}catch(ignore){}\n }\n protectFrame(w.HTMLIFrameElement);\n protectFrame(w.HTMLFrameElement);\n var setAttribute=w.Element&&w.Element.prototype.setAttribute;\n if(setAttribute)w.Element.prototype.setAttribute=function(name,value){\n  var attr=String(name).toLowerCase(),tag=String(this.tagName).toLowerCase();\n  if((attr==='href'&&/^(a|area)$/.test(tag))||(attr==='src'&&/^(iframe|frame)$/.test(tag)))value=localUrl(value);\n  return setAttribute.call(this,name,value);\n };\n})(window,document);\n".getBytes(StandardCharsets.UTF_8);}
 static String inject(String html){
  String tag="<script src=\"/__noon/url-safety.js\"></script>";
  java.util.regex.Matcher head=java.util.regex.Pattern.compile("(?i)<head(?:\\s[^>]*)?>").matcher(html);
  if(head.find())return html.substring(0,head.end())+tag+html.substring(head.end());
  java.util.regex.Matcher root=java.util.regex.Pattern.compile("(?i)<html(?:\\s[^>]*)?>").matcher(html);
  if(root.find())return html.substring(0,root.end())+"<head>"+tag+"</head>"+html.substring(root.end());
  java.util.regex.Matcher doctype=java.util.regex.Pattern.compile("(?i)<!doctype[^>]*>").matcher(html);
  if(doctype.find())return html.substring(0,doctype.end())+tag+html.substring(doctype.end());
  return tag+html;
 }
}
